                or (u.s like 'public.%' and has_function_privilege('authenticated', to_regprocedure(u.s), 'execute'))),
  'knobs_off', (select coalesce(json_agg(json_build_object('key', w.key, 'have', c.value)), '[]'::json)
                  from (values ('land_raid_march_s', '900'), ('round_far_legs', '4'), ('land_raids_enabled', 'false'), ('rounds_enabled', 'false'), ('round_away_hours', '12'), ('honor_enabled', 'false'), ('land_raid_crew_share', '0.15'), ('ammo_enabled', 'false'), ('captain_works_enabled', 'false'), ('captain_work_time_pct', '0.25'), ('captain_work_time_most', '25'), ('combat_rounds_enabled', 'false'), ('round_hull_stop', '40'), ('round_hand_share', '0.1'), ('captain_work_crew_pct', '0.5'), ('captain_work_crew_most', '50'), ('wrecks_yield_enabled', 'false'), ('captain_work_forage', '[{"level": 40, "one_in": 6}, {"level": 80, "one_in": 3}]'), ('land_wood_enabled', 'false'), ('expedition_rounds_enabled', 'false'), ('artifacts_enabled', 'false'), ('artifact_tiers', '[{"rp": 15, "pct": 4, "gold": 400, "tier": "uncommon"}, {"rp": 60, "pct": 1.5, "gold": 2500, "tier": "rare"}, {"rp": 300, "pct": 0.5, "gold": 15000, "tier": "very_rare"}]'), ('captain_places_enabled', 'false'), ('honor_upgrade_base', '5'), ('land_crew_cap', '[10, 2]'), ('land_expedition_enabled', 'false'), ('land_works_are_no_fleets', 'false'), ('land_crew_carry', '1'), ('land_round_stores', '0.3'), ('land_round_stores_crew', '0.01')) w(key, want)
                  left join public.world_config c on c.key = w.key where c.value is distinct from w.want::jsonb),
  'runs', (select json_build_object('rows', count(*), 'out', count(*) filter (where r.state = 'out'), 'overdue_30m', count(*) filter (where r.state = 'out' and r.stop_at < now() - interval '30 minutes'),
                                    'neither_or_both', count(*) filter (where (r.fleet_id is null) = (r.party_id is null))) from public.round_runs r),
  'fleets_on_rounds', (select json_build_object('n', count(*), 'without_run', count(*) filter (where not exists (select 1 from public.round_runs r where r.fleet_id = f.id and r.state = 'out'))) from public.fleets f where f.status = 'ROUNDS'),
  'works', (select json_agg(w.code order by w.ord) from public.round_works w),
  'asks', (select sum(z.ice_min + z.current_min + z.light_min) from public.sea_zones z),
  'seas_bite', (select c.value from public.world_config c where c.key = 'sea_conditions_bite'),
  'places_opened', (select count(*) from public.captain_places_open),
  'badges', (select coalesce(sum(h.balance), 0) from public.honor_balance h),
  'badges_out_of_book', (select count(*) from public.honor_balance h where h.balance <> (select coalesce(sum(k.delta), 0) from public.honor_book k where k.player_id = h.player_id)),
  'artifacts', (select coalesce(sum(q.qty), 0) from public.fleet_artifacts q),
  'job_ms_30m', (select json_build_object('avg', round(avg(r.ms), 1), 'max', max(r.ms)) from public.fleet_job_runs r where r.at > now() - interval '30 minutes')
);
rollback;
